//! Oracle fuzz test for the original function at 0x239468 (generated by `factory gen`; the spec is the static
//! scan's inference: fix it here if the original faults or writes past a block). The port is `kh2_factory::ported::state_active`.
//! Skips without a disc (KH2_ISO or local/iso.txt); fails without one when KH2_REQUIRE_DISC=1.

use kh2_factory::fuzz::*;

const SPEC: Spec = Spec {
    addr: 0x239468,
    args: &[Arg::Ptr(Block { size: 0x60, fields: &[(0x38, 4, Kind::Int), (0x40, 4, Kind::Float), (0x44, 4, Kind::Float), (0x50, 1, Kind::Int)], subs: &[] })],
    floats: 0,
    ret: Ret::Int,
    globals: &[],
    stubs: &[],
    nulls: true,
};

#[test]
fn orig_239468_matches_the_game() {
    let Some(st) = fuzz(&SPEC, 4000, |c| Out::int(kh2_factory::ported::state_active(c.block(0)) as i64)) else { return };
    eprintln!("{} cases equal, {} interpreter steps in {:.3} s", st.cases, st.steps, st.secs);
}
